class PageUtil:
    def __init__(self, data, page_size):
        self.data = data
        self.page_size = page_size
        self.total_items = len(data)
        self.total_pages = self._calculate_total_pages(self.total_items, page_size)

    def _calculate_total_pages(self, total_items, page_size):
        return (total_items + page_size - 1) // page_size

    def get_page(self, page_number):
        if not self._is_valid_page_number(page_number):
            return []

        start_index = self._calculate_start_index(page_number)
        end_index = start_index + self.page_size
        return self._get_page_data(start_index, end_index)

    def _is_valid_page_number(self, page_number):
        return 1 <= page_number <= self.total_pages

    def _calculate_start_index(self, page_number):
        return (page_number - 1) * self.page_size

    def _get_page_data(self, start_index, end_index):
        return self.data[start_index:end_index]

    def get_page_info(self, page_number):
        if not self._is_valid_page_number(page_number):
            return {}

        start_index = self._calculate_start_index(page_number)
        end_index = min(start_index + self.page_size, self.total_items)
        page_data = self._get_page_data(start_index, end_index)

        return {
            "current_page": page_number,
            "per_page": self.page_size,
            "total_pages": self.total_pages,
            "total_items": self.total_items,
            "has_previous": page_number > 1,
            "has_next": page_number < self.total_pages,
            "data": page_data
        }

    def search(self, keyword):
        results = self._search_data(keyword)
        num_results = len(results)
        num_pages = self._calculate_total_pages(num_results, self.page_size)

        return {
            "keyword": keyword,
            "total_results": num_results,
            "total_pages": num_pages,
            "results": results
        }

    def _search_data(self, keyword):
        return [item for item in self.data if keyword in str(item)]
